class Solution {
public:
    int maxNumOfMarkedIndices(std::vector<int>& nums) {
        std::sort(nums.begin(), nums.end());
        int n = nums.size();
        int i = 0;
        for (int j = (n + 1) / 2; j < n; ++j) {
            if (2LL * nums[i] <= nums[j]) {
                i++;
            }
        }
        return 2 * i;
    }
};

class Solution {
    public int maxNumOfMarkedIndices(int[] nums) {
        java.util.Arrays.sort(nums);
        int n = nums.length;
        int i = 0;
        for (int j = (n + 1) / 2; j < n; j++) {
            if (2L * nums[i] <= nums[j]) {
                i++;
            }
        }
        return 2 * i;
    }
}

var maxNumOfMarkedIndices = function(nums) {
    nums.sort((a, b) => a - b);
    const n = nums.length;
    let i = 0;
    for (let j = Math.floor((n + 1) / 2); j < n; j++) {
        if (2 * nums[i] <= nums[j]) {
            i++;
        }
    }
    return 2 * i;
};
